-- Illustrative PostgreSQL starter schema; further production design and migrations required.
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, sso_subject TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, student_number TEXT UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE user_roles (user_id BIGINT REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('super_admin','student')), PRIMARY KEY(user_id,role));
CREATE TABLE clubs (id BIGSERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, category TEXT NOT NULL, mission TEXT, social_handle TEXT, recruiting BOOLEAN DEFAULT TRUE, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')));
CREATE TABLE club_assignments (club_id BIGINT REFERENCES clubs(id), user_id BIGINT REFERENCES users(id), assignment TEXT NOT NULL CHECK(assignment IN ('representative','faculty','member')), PRIMARY KEY(club_id,user_id,assignment));
CREATE TABLE venues (id BIGSERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, capacity INT NOT NULL CHECK(capacity>0), enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE events (id BIGSERIAL PRIMARY KEY, club_id BIGINT NOT NULL REFERENCES clubs(id), title TEXT NOT NULL, description TEXT NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, venue_id BIGINT NOT NULL REFERENCES venues(id), entry_type TEXT NOT NULL CHECK(entry_type IN ('Free','Paid')), status TEXT NOT NULL CHECK(status IN ('draft','pending_faculty','pending_admin','published','cancelled')) DEFAULT 'draft', budget_requested NUMERIC(12,2) DEFAULT 0, resources_requested TEXT, security_requested TEXT, revision INT NOT NULL DEFAULT 1, CHECK(ends_at>starts_at));
CREATE TABLE venue_reservations (id BIGSERIAL PRIMARY KEY, event_id BIGINT UNIQUE NOT NULL REFERENCES events(id), venue_id BIGINT NOT NULL REFERENCES venues(id), time_span TSTZRANGE NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','confirmed','released')), EXCLUDE USING GIST (venue_id WITH =, time_span WITH &&) WHERE (status IN ('pending','confirmed')));
CREATE TABLE approvals (id BIGSERIAL PRIMARY KEY, event_id BIGINT NOT NULL REFERENCES events(id), reviewer_id BIGINT NOT NULL REFERENCES users(id), stage TEXT NOT NULL CHECK(stage IN ('faculty','admin')), action TEXT NOT NULL CHECK(action IN ('approved','rejected')), revision INT NOT NULL, notes TEXT, decided_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE event_rsvps (event_id BIGINT NOT NULL REFERENCES events(id), student_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(event_id,student_id));
CREATE TABLE club_applications (club_id BIGINT NOT NULL REFERENCES clubs(id), student_id BIGINT NOT NULL REFERENCES users(id), reason TEXT, status TEXT DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), PRIMARY KEY(club_id,student_id));
CREATE TABLE club_requests (id BIGSERIAL PRIMARY KEY, applicant_id BIGINT NOT NULL REFERENCES users(id), name TEXT NOT NULL, category TEXT NOT NULL, mission TEXT NOT NULL, requested_faculty_id BIGINT REFERENCES users(id), status TEXT DEFAULT 'pending');
CREATE TABLE audit_log (id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id BIGINT, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), metadata JSONB DEFAULT '{}'::jsonb);
